import{_ as t,o as a,c as o,a2 as c}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Twine - the framework","description":"","frontmatter":{},"headers":[],"relativePath":"guide/twine.md","filePath":"guide/twine.md"}'),r={name:"guide/twine.md"};function i(d,e,n,s,l,h){return a(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="twine-the-framework" tabindex="-1">Twine - the framework <a class="header-anchor" href="#twine-the-framework" aria-label="Permalink to &quot;Twine - the framework&quot;">​</a></h1><p><code>twine</code> is the <strong>opinionated framework layer</strong>: a NestJS-style module/area/lifecycle system for composing a whole datapack out of features. It sits above <code>helix</code> (the un-opinionated compiler) and <code>spool</code> (conveniences) and owns <em>project composition</em> - which features are enabled, how they nest, and when their behaviour runs.</p><p>Where helix deliberately refuses to dictate structure, twine <strong>is</strong> the structure: a feature is a decorated module, modules form a tree, lifecycle runs through fixed hooks, and area ancestry gates tick cost.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><p>A feature is a <strong>module</strong> - a class decorated with <code>@Module({ name, area?, activeByDefault?, imports?, env? })</code>. The app is a tree of modules wired through <code>imports</code>, and <code>DatapackFactory.create(RootModule, opts)</code> walks the enabled tree and emits one <code>Datapack</code>. A module <strong>not reachable through <code>imports</code> is never constructed and emits nothing</strong> - that&#39;s the compile-time disable.</p><h2 id="the-module-lifecycle" tabindex="-1">The module lifecycle <a class="header-anchor" href="#the-module-lifecycle" aria-label="Permalink to &quot;The module lifecycle&quot;">​</a></h2><p>A module may implement any of:</p><ul><li><code>register(dp)</code> - one-off build-time setup (objectives, standalone functions, structures).</li><li><code>onLoad(ctx)</code> - appended to the shared <code>load</code> function; always runs.</li><li><code>onTick(ctx)</code> - appended to the shared <code>tick</code> function, but only reached while every <code>area</code> ancestor is active. Put per-tick work here.</li><li><code>onActivate(ctx)</code> / <code>onDeactivate(ctx)</code> - edge functions for an <code>area</code> module (e.g. summon/despawn a level&#39;s entities).</li></ul><p>An <code>area: true</code> module gates its subtree&#39;s tick cost behind a presence/region check - the parent&#39;s single <code>active</code> check skips the whole subtree for free when dormant.</p><h2 id="one-owned-tick-entry" tabindex="-1">One owned tick entry <a class="header-anchor" href="#one-owned-tick-entry" aria-label="Permalink to &quot;One owned tick entry&quot;">​</a></h2><p>helix auto-tags every function created with the <code>tick</code> tag into vanilla <code>minecraft:tick</code>. twine collapses that to a single owned entry: <code>consolidateTick(dp)</code> (run automatically at the end of <code>DatapackFactory.create</code>) untags every other member and routes the whole pack&#39;s per-tick work through one traceable, gateable list.</p><h2 id="custom-items" tabindex="-1">Custom items <a class="header-anchor" href="#custom-items" aria-label="Permalink to &quot;Custom items&quot;">​</a></h2><p><code>defineItem</code> builds a behavioural item - give/held/attack/use hooks - as an <code>ItemBuilder</code>, on top of helix&#39;s typed <code>Item</code> values.</p><h2 id="state-machines" tabindex="-1">State machines <a class="header-anchor" href="#state-machines" aria-label="Permalink to &quot;State machines&quot;">​</a></h2><p><code>StateMachine</code> is a small typed helper for per-entity/per-player state built on helix <code>Objective</code>s, for features that need explicit states and transitions rather than ad-hoc scoreboard flags.</p><h2 id="full-api-reference" tabindex="-1">Full API reference <a class="header-anchor" href="#full-api-reference" aria-label="Permalink to &quot;Full API reference&quot;">​</a></h2><p>See the generated <a href="/api/twine/">twine API reference</a> for <code>Module</code>, <code>DatapackFactory</code>, <code>defineItem</code>, <code>StateMachine</code>, and the rest of the public surface.</p>',17)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
